{# -----------------------------
  TMS Trip Print (safe lookups)
  Aligns to: Trip (driver→Staff), Route, Passngers, Company.Documents,
             Staff.Documents, Driver.Documents, Vehicle core fields
  ----------------------------- #}

{%- set staff_company_name = frappe.db.get_value('Staff', doc.driver, 'company_name') or '' -%}
{%- set company_name_en   = frappe.db.get_value('Company', staff_company_name, 'company_name') or '' -%}
{%- set company_name_ar   = frappe.db.get_value('Company', staff_company_name, 'company_name_arabic') or '' -%}
{%- set company_logo      = frappe.db.get_value('Company', staff_company_name, 'company_logo') -%}
{%- set company_phone     = frappe.db.get_value('Company', staff_company_name, 'phone_no') -%}

{# Vehicle details are not stored on Trip in TMS; fetch directly from Vehicle #}
{%- set vehicle_make   = doc.assigned_vehicle and frappe.db.get_value('Vehicle', doc.assigned_vehicle, 'make') or '' -%}
{%- set vehicle_model  = doc.assigned_vehicle and frappe.db.get_value('Vehicle', doc.assigned_vehicle, 'model') or '' -%}
{%- set vehicle_regno  = doc.assigned_vehicle and frappe.db.get_value('Vehicle', doc.assigned_vehicle, 'registration_no') or '' -%}
{%- set license_plate  = doc.assigned_vehicle and frappe.db.get_value('Vehicle', doc.assigned_vehicle, 'license_plate') or '' -%}

{# Driver (Staff) basics #}
{%- set driver_full    = frappe.db.get_value('Staff', doc.driver, 'full_name') or doc.driver -%}
{%- set driver_mobile  = frappe.db.get_value('Staff', doc.driver, 'mobile_no') or '' -%}

{# Try to find a Driver doc that matches this Staff full_name to read its Documents #}
{%- set driver_docname = frappe.db.get_value('Driver', {'full_name': driver_full}, 'name') -%}

{# Pull Company & Staff & Driver document numbers (Iqama, Passport, CR, Reg, License) #}
{%- set iqama_no = '' -%}
{%- set passport_no = '' -%}
{%- if doc.driver -%}
  {%- set staff_doc = frappe.get_doc('Staff', doc.driver) -%}
  {%- for d in staff_doc.documents or [] -%}
    {%- set dtype = (d.document_type or '').strip() -%}
    {%- if dtype in ['Iqama','Residency','Resident ID'] and not iqama_no -%}{%- set iqama_no = d.document_no or '' -%}{%- endif -%}
    {%- if dtype in ['Passport'] and not passport_no -%}{%- set passport_no = d.document_no or '' -%}{%- endif -%}
  {%- endfor -%}
{%- endif -%}

{%- set driver_license_no = '' -%}
{%- if driver_docname -%}
  {%- set driver_doc = frappe.get_doc('Driver', driver_docname) -%}
  {%- for d in driver_doc.documents or [] -%}
    {%- set dtype = (d.document_type or '').strip() -%}
    {%- if dtype in ['Driving License','Driver License','License'] and not driver_license_no -%}
      {%- set driver_license_no = d.document_no or '' -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}

{%- set cr_no = '' -%}
{%- set company_registration_details = '' -%}
{%- if staff_company_name -%}
  {%- set comp = frappe.get_doc('Company', staff_company_name) -%}
  {%- for d in comp.documents or [] -%}
    {%- set dtype = (d.document_type or '').strip() -%}
    {%- if dtype in ['CR','Commercial Registration','Commercial Registration (CR)'] and not cr_no -%}
      {%- set cr_no = d.document_no or '' -%}
    {%- endif -%}
    {%- if dtype in ['Registration','Transport License','License'] and not company_reg_no -%}
      {%- set company_registration_details = d.document_no or '' -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}

{# Utility: badge color for expiries #}
{%- macro expiry_badge(exp) -%}
  {%- if not exp -%}
    <span>-</span>
  {%- else -%}
    {%- set days = frappe.utils.date_diff(exp, frappe.utils.today()) -%}
    {%- if days <= 0 -%}
      <span style="color:#b00020;font-weight:600">{{ frappe.utils.formatdate(exp) }} (Expired)</span>
    {%- elif days <= 60 -%}
      <span style="color:#e65100;font-weight:600">{{ frappe.utils.formatdate(exp) }} ({{ days }} days)</span>
    {%- else -%}
      <span>{{ frappe.utils.formatdate(exp) }}</span>
    {%- endif -%}
  {%- endif -%}
{%- endmacro -%}

<style>
  @media print {.page { page-break-after: always; }}
  body { font-family: 'Ubuntu', sans-serif; font-size: 14px; }
  .header, .footer { display:flex; justify-content:space-between; align-items:center; width:100%; }
  .header { border-bottom:1px solid #ccc; padding:8px 0; }
  .footer { border-top:1px solid #ccc; padding:6px 0; font-size:12px; color:#444; margin-top:20px;}
  .logo img { width:110px; height:auto; }
  .names { text-align:right; }
  .names .en { font-size:16px; margin:0; }
  .names .ar { font-size:20px; direction:rtl; margin:0; }
  .content { padding:16px 0; }
  table { width:100%; border-collapse:collapse; margin-top:10px; }
  th, td { border:1px solid #aaa; padding:6px; text-align:left; }
  th { background:#efdfdf; color:#07417b; font-weight:800; }
  h4 { margin:16px 0 8px; }
  .muted { color:#666; }
  .section-title { margin-top:18px; font-weight:700; }
</style>

<div class="page">
  <div class="header">
    <div class="logo">
      {% if company_logo %}<img src="{{ company_logo }}">{% endif %}
    </div>
    <div class="names">
      <div class="en">{{ company_name_en or '' }}</div>
      <div class="ar">{{ company_name_ar or '' }}</div>
    </div>
  </div>

  <div class="content">
    <table>
      <tbody>
        <tr>
          <th>Driver</th>
          <td>{{ driver_full }}</td>
          <th>Mobile</th>
          <td>{{ driver_mobile or '-' }}</td>
        </tr>
        <tr>
          <th>Iqama / ID</th>
          <td>{{ iqama_no or '-' }}</td>
          <th>Passport</th>
          <td>{{ passport_no or '-' }}</td>
        </tr>
        <tr>
          <th>Vehicle</th>
          <td>{{ vehicle_make }} {{ vehicle_model }} {% if doc.assigned_vehicle %} ({{ doc.assigned_vehicle }}){% endif %}</td>
          <th>Reg. No / Plate</th>
          <td>{{ vehicle_regno or '-' }}{% if license_plate %} / {{ license_plate }}{% endif %}</td>
        </tr>
        <tr>
          <th>Date</th>
          <td>{{ frappe.utils.formatdate(doc.date) }}</td>
          <th>Status</th>
          <td>{{ doc.trip_status }}</td>
        </tr>
        <tr>
          <th>From</th>
          <td>{{ doc.from_location }}</td>
          <th>To</th>
          <td>{{ doc.to_location }}</td>
        </tr>
        <tr>
          <th>Departure</th>
          <td>{{ frappe.utils.format_datetime(doc.departure) if doc.departure else '-' }}</td>
          <th>Arrival</th>
          <td>{{ frappe.utils.format_datetime(doc.arrival) if doc.arrival else '-' }}</td>
        </tr>
        <tr>
          <th>Distance</th>
          <td>{{ doc.distance }} km</td>
          <th>Duration</th>
          <td>{{ doc.duration or '-' }}</td>
        </tr>
        <tr>
          <th>Co-Driver</th>
          <td colspan="3">{{ doc.co_driver or '-' }}</td>
        </tr>
      </tbody>
    </table>

    <h4>Passengers</h4>
    <table>
      <thead>
        <tr>
          <th>#</th>
          <th>Passenger</th>
          <th>Passport/ID</th>
          <th>Nationality</th>
          <th>Contact</th>
        </tr>
      </thead>
      <tbody>
        {% for row in doc.passngers %}
          <tr>
            <td>{{ loop.index }}</td>
            <td>{{ row.passenger_name }}</td>
            <td>{{ row.idpassport_no or '' }}</td>
            <td>{{ row.nationality or '' }}</td>
            <td>{{ row.contact_no or '' }}</td>
          </tr>
        {% endfor %}
        {% if (doc.passngers or [])|length == 0 %}
          <tr><td colspan="5" class="muted">No passengers added.</td></tr>
        {% endif %}
      </tbody>
    </table>

    {% if staff_company_name %}
      <div class="section-title">Company Info</div>
      <table>
        <tbody>
          <tr>
            <th>Company (EN/AR)</th>
            <td colspan="3">{{ company_name_en or '-' }} / {{ company_name_ar or '-' }}</td>
          </tr>
          <tr>
            <th>CR No</th>
            <td>{{ cr_no or '-' }}</td>
            <th>Registration / License</th>
            <td>{{ company_registration_details or '-' }}</td>
          </tr>
          <tr>
            <th>Phone</th>
            <td colspan="3">{{ company_phone_no or  '-' }}</td>
          </tr>
        </tbody>
      </table>

      {# Optional: Show detailed Company / Driver / Vehicle documents with expiry color #}
      <div class="section-title">Documents (Company / Driver / Vehicle)</div>
      <table>
        <thead>
          <tr>
            <th>Entity</th>
            <th>Document Type</th>
            <th>Number</th>
            <th>Issue Date</th>
            <th>Expiry</th>
          </tr>
        </thead>
        <tbody>
          {% for d in (comp.documents or []) %}
            <tr>
              <td>Company</td>
              <td>{{ d.document_type }}</td>
              <td>{{ d.document_no or '-' }}</td>
              <td>{{ frappe.utils.formatdate(d.issue_date) if d.issue_date else '-' }}</td>
              <td>{{ expiry_badge(d.expiry_date) }}</td>
            </tr>
          {% endfor %}
          {% if driver_docname %}
            {% for d in (driver_doc.documents or []) %}
              <tr>
                <td>Driver</td>
                <td>{{ d.document_type }}</td>
                <td>{{ d.document_no or '-' }}</td>
                <td>{{ frappe.utils.formatdate(d.issue_date) if d.issue_date else '-' }}</td>
                <td>{{ expiry_badge(d.expiry_date) }}</td>
              </tr>
            {% endfor %}
          {% endif %}
          {% if doc.assigned_vehicle %}
            {%- set vdocs = frappe.get_all('Documents', filters={'parenttype':'Vehicle','parent': doc.assigned_vehicle}, fields=['document_type','document_no','issue_date','expiry_date']) -%}
            {% for d in vdocs %}
              <tr>
                <td>Vehicle</td>
                <td>{{ d.document_type }}</td>
                <td>{{ d.document_no or '-' }}</td>
                <td>{{ frappe.utils.formatdate(d.issue_date) if d.issue_date else '-' }}</td>
                <td>{{ expiry_badge(d.expiry_date) }}</td>
              </tr>
            {% endfor %}
          {% endif %}
        </tbody>
      </table>
    {% endif %}

    {% if doc.qr_code %}
      <div style="text-align:center; margin-top:16px;">
        <img src="{{ doc.qr_code }}" style="width:140px;"><br>
        <small>Scan to open this trip</small>
      </div>
    {% endif %}
  </div>

  <div class="footer">
    <div>CR: {{ cr_no or '-' }}</div>
    <div>Phone: {{ company_phone_no or  '-' }}</div>
  </div>
</div>
